/* === 民国-电影首映 感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12老师的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影. === */

/* --- 1. 字体引入 (中英混排矩阵) --- */
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;1,400&display=swap'); 
@import url("https://fontsapi.zeoseven.com/440/main/result.css"); 
@import url("https://fontsapi.zeoseven.com/45/main/result.css");  
@import url("https://fontsapi.zeoseven.com/496/main/result.css"); 
@import url("https://fontsapi.zeoseven.com/229/main/result.css"); 

/* --- 2. 核心颜色与样式变量 (严格黑夜模式) --- */
:root {
    --theme-bg-color: #080808; /* 深渊黑底板 */
    --paper-bg: #141414; /* 炭黑色报纸纸张 */
    --text-main: #E5E5E5; /* 泛黄的褪色白字 */
    --text-subtle: #8A8A8A; /* 灰白字 */
    --border-color: #555555; /* 报纸暗灰边框 */

    --font-english: 'Playfair Display', serif;
    --font-main: "Huiwen-Fangsong", var(--font-english), serif;
    --font-quote: "PING FANG JIANG NAN TI", var(--font-english), serif;
    --font-code: "nzgrRuYinZouZhangKai", monospace;
    --font-title: "临海体", var(--font-english), serif;
}

/* --- 3. 全局样式：彻底无阴影、暗黑复古背景 --- */
* { box-shadow: none !important; border-style: none !important; }
body { 
    background-color: var(--theme-bg-color) !important; 
    background-image: url('https://www.transparenttextures.com/patterns/rice-paper.png') !important; /* 增加暗黑宣纸颗粒 */
    background-attachment: fixed;
    color: var(--text-main); 
    font-family: var(--font-main); 
    font-weight: normal; 
}
#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; border: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 120px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); color: var(--text-main); font-weight: normal; border-bottom: 2px solid var(--border-color) !important; border-radius: 0 !important; }

/* --- 4. 顶部导航栏 & 抽屉背景 (图标反相发白，完美适配黑底) --- */
#top-settings-holder { position:relative; background-color: rgba(15, 15, 15, 0.9); border-bottom: 1px solid var(--border-color) !important; }

/* 彻底隐藏原生 FontAwesome 图标字体 */
#top-settings-holder .drawer-icon::before, #top-settings-holder .fa-fw::before { content: '' !important; font-size: 0 !important; display: none !important; }

/* 统一设定贴图容器样式 */
#top-settings-holder .drawer-icon, #top-settings-holder .fa-fw { 
    width: 35px !important; height: 40px !important; 
    background-size: contain !important; 
    background-repeat: no-repeat !important; 
    background-position: center !important; 
    transition: all 0.4s ease; 
    filter: invert(1) grayscale(100%) brightness(0.8); /* 黑夜模式反相 */
    display: inline-block;
}
#top-settings-holder .drawer-icon:hover, #top-settings-holder .fa-fw:hover { 
    transform: translateY(-3px) scale(1.1); 
    filter: invert(1) grayscale(100%) brightness(1.2); 
}

/* === 导航栏贴图精准映射 (最高优先级 !important 锁定) === */

/* 1. AI响应配置 (fa-sliders) */
#ai-config-button .drawer-icon, .drawer-icon.fa-sliders { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/lOG2/1135X1134/2026-05-03%2520185011.png/webp') !important; }

/* 2. API连接 (fa-plug) */
#sys-settings-button .drawer-icon, .drawer-icon.fa-plug { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/rVKq/1233X1127/2026-05-03%2520185016.png/webp') !important; }

/* 3. AI回复格式化 (fa-font) */
#advanced-formatting-button .drawer-icon, .drawer-icon.fa-font { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/SV25/1179X1176/2026-05-03%2520185024.png/webp') !important; }

/* 4. 世界信息 (fa-book-atlas) */
#WI-SP-button .drawer-icon, .drawer-icon.fa-book-atlas { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/NlpC/1273X1258/2026-05-03%2520185035.png/webp') !important; }

/* 5. 用户设置 (fa-user) */
#user-settings-button .drawer-icon, .drawer-icon.fa-user { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/Xaby/1336X1244/2026-05-03%2520185042.png/webp') !important; }

/* 6. 背景图 (fa-image) */
#backgrounds-button .drawer-icon, .drawer-icon.fa-image { 
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/LqPi/919X920/2026-05-03%2520190237.png/webp') !important; 
}
/* 7. 扩展 (fa-cubes) */
#extensions-settings-button .drawer-icon, .drawer-icon.fa-cubes { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/LqPi/919X920/2026-05-03%2520190237.png/webp') !important; }

/* 8. 记忆表格 (fa-bars-progress) */
#table_database_settings_drawer .drawer-icon, .drawer-icon.fa-bars-progress { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/LqPi/919X920/2026-05-03%2520190237.png/webp') !important; }

/* 9. 用户角色管理 (fa-face-smile) */
#persona-management-button .drawer-icon, .drawer-icon.fa-face-smile { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/LqPi/919X920/2026-05-03%2520190237.png/webp') !important; }

/* 10. 角色卡 (fa-address-card) */
#character_popup_button .drawer-icon, #rm_button .drawer-icon, .drawer-icon.fa-address-card { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/LqPi/919X920/2026-05-03%2520190237.png/webp') !important; }


/* --- 抽屉与弹窗背景图 (保留极暗遮罩) --- */
.drawer-content, dialog.popup .popup-body, #dialogue_popup {
    background-image: linear-gradient(rgba(12, 12, 12, 0.93), rgba(12, 12, 12, 0.97)), url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/TfXC/1152X656/a5e6fb252b8fe2895e6ebca591269067.jpg/webp') !important;
    background-size: cover; background-position: center;
    border-radius: 0 !important; color: var(--text-main) !important;
    border: 1px solid var(--border-color) !important;
}
/* --- 5. 底部悬浮输入栏 (黑底打字机) --- */
#form_sheld { position: absolute !important; bottom: 20px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; }
#send_form { width: 90% !important; max-width: 800px !important; pointer-events: auto; }

#send_form, body.no-blur #send_form { 
    border-radius: 0 !important; 
    background-color: var(--paper-bg) !important; 
    padding: 10px 15px !important; 
    border-top: 3px double var(--border-color) !important; 
    border-bottom: 3px double var(--border-color) !important; 
    box-shadow: none !important; 
    transition: all 0.3s ease !important; 
}
#rightSendForm, #leftSendForm { gap: 15px; }
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: var(--text-main) !important; font-size: 1.15rem !important; font-family: var(--font-main); }

#nonQRFormItems { position: relative; }
#send_textarea::placeholder { color: transparent !important; text-shadow: none !important; }

/* 伪提示词 (完美居中排版) */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    content: '撰写首映专访稿件... ✒️🎞️'; 
    color: var(--text-subtle); 
    position: absolute; 
    top: 50%; transform: translateY(-50%); 
    left: 0; right: 0; 
    text-align: center; 
    font-family: var(--font-quote); 
    font-size: clamp(1rem, 2.5vw, 1.2rem); 
    pointer-events: none; 
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    opacity: 0.7; 
    animation: fade-pulse 2s infinite alternate;
}
@keyframes fade-pulse { 0% { opacity: 0.3; } 100% { opacity: 0.8; } }

/* 底栏黑白贴图 */
#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before, #mes_impersonate::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button, #mes_impersonate { 
    width: 38px; height: 38px; 
    background-size: contain; background-repeat: no-repeat; background-position: center; 
    transition: transform 0.3s ease; font-size: 0; border: none; background-color: transparent; 
}
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover { transform: scale(1.1); filter: invert(1) grayscale(100%) opacity(1); }

#options_button, #ai_retry_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/QpJz/2944X2256/%25E9%25BB%2591%25E7%2599%25BD%25E6%2597%25A0%25E5%25B8%25B8%25E7%25B4%25A0%25E6%259D%2590%25E9%2593%25BA%2520%2847%29.png/webp'); }
#send_form #extensionsMenuButton, #auto_completion_button, #mes_impersonate { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/Z1vy/2944X2644/%25E9%25BB%2591%25E7%2599%25BD%25E6%2597%25A0%25E5%25B8%25B8%25E7%25B4%25A0%25E6%259D%2590%25E9%2593%25BA%2520%2839%29.png/webp'); }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/aX4d/1700X2052/%25E9%25BB%2591%25E7%2599%25BD%25E6%2597%25A0%25E5%25B8%25B8%25E7%25B4%25A0%25E6%259D%2590%25E9%2593%25BA%2520%2838%29.png/webp'); }

/* --- 6. 核心：消息框排版 (整体黑夜版报纸双层边框！) --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 6px !important; /* 给内外边框留出缝隙 */
    margin: 50px auto 60px !important; 
    width: 90%; max-width: 850px; 
    background-color: var(--paper-bg) !important;
    position: relative;
    border: 6px double var(--border-color) !important; /* 最外层双线报纸主边框 */
    outline: 1px solid var(--border-color); /* 内侧细边框 */
    outline-offset: -5px;
}

/* --- 消息框顶部背景图 (杜绝重叠) --- */
.mes .mesAvatarWrapper {
    display: block; padding: 0;
    width: 100%; 
    height: 360px !important; 
    min-height: 360px !important;
    background-size: cover; background-position: top center; background-repeat: no-repeat;
    position: relative; z-index: 5; overflow: visible !important;
    border-radius: 0;
    border-bottom: 2px dashed var(--border-color) !important; 
    background-color: transparent !important;
    margin-bottom: 0 !important; 
}
/* AI消息框顶图 */
.mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260504/Pqmw/4578X2298/%25E6%258A%25A5%25E7%25BA%25B8%25E5%25BA%2595%25E5%259B%25BE1_compressed.png/webp'); }
/* User消息框顶图 */
.mes[is_user="true"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260504/Ul5h/4578X2298/%25E6%258A%25A5%25E7%25BA%25B8%25E5%25BA%2595%25E5%259B%25BE2_compressed.png/webp'); }

/* --- 明星相馆：超大复古头像框 (黑底白边，不随背景反相) --- */
.mes .avatar {
    position: absolute;
    top: 70px; 
    width: 180px !important; height: 240px !important; 
    background: #111 !important; /* 相框变黑 */
    padding: 8px 8px 35px 8px !important; 
    z-index: 30; display: flex !important; align-items: flex-start; justify-content: center;
    border-radius: 0 !important; 
    border: 1px solid #444 !important;
    filter: grayscale(100%) contrast(1.1); /* 头像本身变黑白胶片 */
    transition: all 0.5s ease;
}
.mes .avatar:hover { transform: scale(1.03); border-color: #888 !important; }

.mes[is_user="false"] .avatar { left: 40px; }
.mes[is_user="true"] .avatar { right: 40px; left: auto; }

.mes .avatar img { width: 100% !important; height: 100% !important; object-fit: cover !important; border-radius: 0 !important; }

/* 暗黑胶片说明文字 */
.mes .avatar::after {
    content: '◎首映独家留影'; 
    position: absolute;
    bottom: 8px; left: 0; right: 0; text-align: center;
    font-family: var(--font-main); font-size: 14px; color: #AAA; letter-spacing: 2px;
}

/* --- 楼层与时间戳 (报眼) --- */
.mes .mesIDDisplay, .mes .mes_timer {
    position: absolute !important; top: -15px !important; 
    background-color: var(--theme-bg-color) !important; padding: 4px 12px !important;
    color: var(--text-main) !important; font-size: 14px !important; font-family: var(--font-code) !important; 
    letter-spacing: 2px !important; white-space: nowrap; z-index: 40 !important;
    border: 1px solid var(--border-color) !important;
    border-radius: 0 !important;
}
.mes .mesIDDisplay { left: 10px !important; }
.mes .mes_timer { right: 10px !important; left: auto !important; }
.mesIDDisplay::before { content: '【第 '; }
.mesIDDisplay::after { content: ' 版】'; }

/* --- 名字：与正文分离，防止重叠 --- */
.mes > .ch_name, .mes .mes_block > .ch_name { 
    display: flex !important; position: relative !important; 
    background: transparent !important; border: none !important;
    margin-bottom: 10px !important; 
    padding: 25px 50px 0 50px !important; 
    z-index: 20 !important; width: 100% !important; box-sizing: border-box;
}
.mes[is_user="false"] > .ch_name, .mes[is_user="false"] .mes_block > .ch_name { justify-content: flex-start; text-align: left; }
.mes[is_user="true"] > .ch_name, .mes[is_user="true"] .mes_block > .ch_name { justify-content: flex-end; text-align: right; }

.mes .ch_name .name_text { 
    font-family: var(--font-title); 
    font-size: 28px !important; 
    letter-spacing: 3px; 
    color: var(--text-main) !important; 
    border-bottom: 3px double var(--border-color); 
    padding-bottom: 5px;
    display: block; 
}
.mes[is_user="false"] .ch_name .name_text::before { content: '主演：'; font-size: 18px; color: var(--text-subtle); font-family: var(--font-code); }
.mes[is_user="true"] .ch_name .name_text::before { content: '特约撰稿：'; font-size: 18px; color: var(--text-subtle); font-family: var(--font-code); }

/* ========================================================
   正文排版：独立区块
======================================================== */
.mes .mes_block { 
    margin-top: 0 !important; 
    background-color: transparent !important; 
    padding: 10px 50px 40px 50px !important; 
    position: relative; 
    border: none !important; 
    border-radius: 0 !important;
    min-height: 120px !important; z-index: 10; 
}

.mes .mes_text, .mes_reasoning { background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; position: relative; z-index: 10 !important; }

/* 极暗夜水印 */
.mes_block .mes_text::after {
    content: '『 民 國 影 業 』\A 首 映 專 刊'; white-space: pre;
    position: absolute; bottom: 20%; color: rgba(255, 255, 255, 0.02);
    font-family: var(--font-title); font-size: 60px; text-align: center; font-weight: bold; transform: rotate(-15deg);
    z-index: 0; pointer-events: none; user-select: none;
    left: 0; right: 0;
}

/* 黑白电影思维链自定义 */
#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; border-radius: 0; padding: 0 !important; margin-bottom: 15px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { 
    content: "🎥 胶片暗房冲印中... (导演构思)"; 
    font-family: var(--font-quote); font-size: 20px !important; 
    color: var(--text-subtle); visibility: visible; letter-spacing: 1px; 
}
.mes_reasoning { padding-left: 20px !important; margin-bottom: 30px !important; color: var(--text-subtle); font-family: var(--font-quote); font-size: 1.1em; position: relative; }
.mes_reasoning::before { 
    content: ''; position: absolute; left: 0; top: 5px; bottom: 5px; width: 3px; 
    background: var(--border-color);
}
.mes .mes_text { line-height: 2.4; color: var(--text-main); font-size: 17px; text-align: justify; letter-spacing: 1px; }

/* 暗黑打字指示器 (反相变白) */
#typing_indicator { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/aX4d/1700X2052/%25E9%25BB%2591%25E7%2599%25BD%25E6%2597%25A0%25E5%25B8%25B8%25E7%25B4%25A0%25E6%259D%2590%25E9%2593%25BA%2520%2838%29.png/webp') !important; background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; animation: flicker 0.5s infinite alternate; border: none !important; height: 50px !important; width: 50px !important; margin: 15px auto !important; filter: invert(1) grayscale(100%); }
#typing_indicator .dot { display: none !important; }
@keyframes flicker { 0% { opacity: 0.5; transform: scale(0.98); } 100% { opacity: 1; transform: scale(1.02); } }

/* --- 悬浮按钮 (纯黑夜图章) --- */
.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 8px; opacity: 0; transition: opacity 0.4s ease; pointer-events: auto !important; margin-top: 15px; position: relative; z-index: 15; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button { background-color: var(--paper-bg) !important; color: var(--text-main) !important; padding: 6px !important; border-radius: 0 !important; border: 1px solid var(--border-color) !important; cursor: pointer; transition: all 0.3s ease; font-size: 14px !important; }
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover { background-color: var(--text-main) !important; color: var(--paper-bg) !important; }

/* --- 全局UI设定 (极致暗黑，取消圆角) --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, #power-user-options-block h4, #InstructSettingsColumn h4, #SystemPromptColumn h4, #ContextSettings h4, .persona_management_global_settings h4, #character_popup h4, #AdvancedFormatting h4, #rm_group_chats_block h4, div[name*='HandlingToggles'] h4, div[name*='MiscellaneousToggles'] h4 { background: transparent !important; border-radius: 0 !important; padding: 12px 0 !important; margin-bottom: 10px !important; color: var(--text-main) !important; border-bottom: 1px solid var(--border-color) !important; font-family: var(--font-title); font-size: 1.2em; }
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: transparent !important; color: var(--text-main) !important; border-radius: 0 !important; padding: 10px !important; border: 1px solid var(--border-color) !important; font-family: var(--font-main); }
input:focus, textarea:focus, select:focus { outline: none !important; border: 1px solid var(--text-main) !important; background-color: rgba(255,255,255,0.05) !important; }
.menu_button { background-color: transparent !important; color: var(--text-main) !important; transition: all 0.3s ease; border-radius: 0 !important; border: 1px solid var(--border-color) !important; }
.menu_button:hover, .menu_button.active, .menu_button.world_set, .menu_button.fav_on, #left-nav-panel .menu_button.selected { background-color: var(--text-subtle) !important; color: var(--paper-bg) !important; border-color: var(--text-subtle) !important; }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--text-subtle) !important; }

dialog.popup { background-color: transparent !important; }
dialog.popup .popup-body::before, #dialogue_popup::before { display: none; }

#dialogue_popup { z-index: 10000 !important; pointer-events: auto !important; background-color: var(--paper-bg) !important; border: 2px solid var(--border-color) !important; border-radius: 0 !important; }
#dialogue_del_mes_ok, #dialogue_del_mes_cancel { background-color: transparent !important; color: var(--text-main) !important; border-radius: 0 !important; padding: 12px 24px !important; margin: 10px 8px !important; transition: all 0.3s ease !important; border: 1px solid var(--border-color) !important; }
#dialogue_del_mes_ok:hover { background-color: var(--border-color) !important; color: var(--text-main) !important; }
#dialogue_del_mes_cancel:hover { background-color: var(--text-subtle) !important; color: var(--paper-bg) !important; }

/* --- 手机端适配调整 (同步调整双层边框防重叠) --- */
@media (max-width: 768px) {
    .mes { margin: 30px auto 40px !important; width: 95%; padding: 4px !important; }
    .mes .mesAvatarWrapper { height: 230px !important; min-height: 230px !important; }
    .mes .avatar { width: 120px !important; height: 160px !important; top: 40px; }
    .mes[is_user="false"] .avatar { left: 15px; }
    .mes[is_user="true"] .avatar { right: 15px; }
    .mes > .ch_name, .mes .mes_block > .ch_name { padding: 15px 25px 0 25px !important; }
    .mes .ch_name .name_text { font-size: 20px !important; }
    .mes .mes_block { padding: 10px 25px 30px 25px !important; }
    .mes_block .mes_text::after { font-size: 40px; }
}
